MAP
NAME "heatmap-test"
STATUS ON
SIZE 800 600
EXTENT -180 -90 180 90
UNITS DD
SHAPEPATH "../data/"
SYMBOLSET "../etc/symbols.txt"
IMAGECOLOR 255 255 255
#
# Start of layer definitions
#

LAYER
  NAME "heatmap"
  TYPE raster
  STATUS ON  
  CONNECTIONTYPE kerneldensity
  CONNECTION "points"
  PROCESSING "RANGE_COLORSPACE=HSL"
  PROCESSING "KERNELDENSITY_RADIUS=20"
  PROCESSING "KERNELDENSITY_ATTRIBUTE=RANK_MIN"
  PROCESSING "KERNELDENSITY_COMPUTE_BORDERS=ON"
  PROCESSING "KERNELDENSITY_NORMALIZATION=AUTO"
  OFFSITE 0 0 0
  CLASS
    STYLE
      COLORRANGE  "#0000ff00"  "#0000ffff"
      DATARANGE 0 32
    END
    STYLE
      COLORRANGE  "#0000ffff"  "#ff0000ff"
      DATARANGE 32 255
    END
  END
END 

LAYER
  NAME "points"
  DATA "./ne_10m_populated_places"
  TYPE POINT
  STATUS ON
  CLASS
    STYLE
      SIZE 5
      SYMBOL "circle"
      COLOR 200 200 200
      OUTLINECOLOR 0 0 0
    END
  END
END

END # Map File
